// This file is generated by AI.

// 提交历史对话框的跨打开状态。
//
// 为什么必须是**模块**作用域: 对话框关闭时组件会卸载, 组件里的变量随之丢失 —— 而"关掉去看一眼
// 别处 (点文件开差异 / 点遮罩 / 按 Esc) 再回来接着查一段历史"正是最需要它活下来的场景。
//
// ⚠️ 这里踩过一次: 那段状态原本写在组件实例脚本里 (注释还写着"模块作用域"), 但 Svelte 5 的实例
// 脚本是**每次挂载一份**, 于是每次重新打开都归零 —— 表现是"展开的提交与滚动位置从来记不住"。
// 状态要跨挂载存活, 就只有模块作用域 (`<script module>` 或独立模块), 没有第三条路。

import type { GitCommit, GitCommitFile } from '../commands/git';

export interface HistoryState {
  projectPath: string;
  commits: GitCommit[];
  /** 已展开的提交 id */
  expanded: string[];
  /** 每个提交的文件列表 (展开时才取) */
  files: Record<string, GitCommitFile[]>;
  scrollTop: number;
}

let current: HistoryState | null = null;

/**
 * 取某个项目的历史状态。
 *
 * 同一个项目返回**同一个对象** —— 对话框直接在上面读写, 不复制也不重新创建; 换了项目就换一份
 * 新的, 因为上一个项目的展开项与滚动位置对新项目没有任何意义。
 */
export function historyStateFor(projectPath: string): HistoryState {
  if (current?.projectPath !== projectPath) {
    current = { projectPath, commits: [], expanded: [], files: {}, scrollTop: 0 };
  }
  return current;
}

/** 丢弃状态: 用户按底部的「关闭」按钮 = 这段历史看完了, 下次从干净的状态开始。 */
export function clearHistoryState(): void {
  current = null;
}
